package core

// RealWorld is one place an entry shows up in real software: a short title,
// a sentence saying where and how, and, when there is one, a runnable
// program in examples/ that uses it the way production code would.
type RealWorld struct {
	Title   string `json:"title"`
	Where   string `json:"where"`
	Example string `json:"example,omitempty"` // "examples/leaderboard"
}

// use is a real-world use without a program; ex is one with a program in
// examples/.
func use(title, where string) RealWorld { return RealWorld{Title: title, Where: where} }

func ex(title, where, dir string) RealWorld {
	return RealWorld{Title: title, Where: where, Example: "examples/" + dir}
}

